// saucecontrol/Compact-ICC-Profiles, sRGB-v2-micro.icc, CC0-1.0.
// 456 bytes; SHA-256 0a8a33aea66a6f154a5642ebe168ef287e73265d9f7b51c42a45e6eedbacda7a.
const SRGB_V2_MICRO_BASE64 =
  '';

export const srgbIccProfileBytes = () => {
  const binary = atob(SRGB_V2_MICRO_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
};
